#include <vector>

class Solution {
public:
    int xorQueries(std::vector<int>& nums, std::vector<std::vector<int>>& queries) {
        long long MOD = 1000000007;
        for (const auto& q : queries) {
            int l = q[0], r = q[1];
            long long val = q[2];
            for (int i = l; i <= r; ++i) {
                nums[i] = (nums[i] * val) % MOD;
            }
        }
        int ans = 0;
        for (int x : nums) {
            ans ^= x;
        }
        return ans;
    }
};

class Solution {
    public int xorQueries(int[] nums, int[][] queries) {
        long MOD = 1000000007L;
        for (int[] q : queries) {
            int l = q[0], r = q[1];
            long val = q[2];
            for (int i = l; i <= r; i++) {
                nums[i] = (int) (((long) nums[i] * val) % MOD);
            }
