var xorQueries = function(nums, queries) {
    const MOD = 1000000007n;
    const bigNums = nums.map(x => BigInt(x));
    for (const [l, r, val] of queries) {
        const bigVal = BigInt(val);
        for (let i = l; i <= r; i++) {
            bigNums[i] = (bigNums[i] * bigVal) % MOD;
        }
    }
    let ans = 0n;
    for (const x of bigNums) {
        ans ^= x;
    }
    return Number(ans);
};
